function group(type,count,extra={}){return Array.from({length:count},()=>({type,...extra}));}
export function wavesFor(mapIndex){const m=MAPS[mapIndex],protection=['agni','varuna','indra','prithvi','vayu'][mapIndex];return [
 [...group('pisacha',7),...group('swift',2)],
 [...group('pisacha',7),...group('rakshasa',3)],
 [...group('swift',5),...group('winged',3),...group('yaksha',1,{protection})],
 [...group('shade',4),...group('rakshasa',4),...group('pisacha',5)],
 [...group('yaksha',3,{protection}),...group('asura',4),...group('swift',5)],
 [...group('winged',5),...group('shade',4),...group('yaksha',2,{protection:'prithvi'})],
 [...group('asura',6),...group('rakshasa',4,{protection:'indra'}),...group('swift',6)],
 [...group('asura',4),...group('boss',1,{protection:m.bossProtection,boon:m.boss}),...group('shade',3),...group('yaksha',2,{protection:'durga'})]
];}
export function challengePassed(b){switch(b.map.challengeKind){case'four':return b.usedDeities.length<=4;case'early':return b.earlyCalls>=2;case'exalted':return b.shrines.filter(s=>s.level===3).length>=3;case'patient':return b.interventions===0;case'seven':return b.usedDeities.length===7;default:return false;}}
export function enemyKey(spec,mapIndex){return spec.type==='boss'?`boss:${MAPS[mapIndex].id}`:`${spec.type}:${spec.protection||'none'}`;}
